import { Box, Dialog, DialogContent, IconButton, Typography } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import BlocksText from "../components/BlocksText";
import type { BlocksContent } from "../types/home";

type PlanLearnMoreModalProps = {
  open: boolean;
  title?: string;
  content?: BlocksContent;
  onClose: () => void;
};

export default function PlanLearnMoreModal({
  open,
  title,
  content,
  onClose,
}: PlanLearnMoreModalProps) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      scroll="paper"
      aria-labelledby="plan-learn-more-title"
      PaperProps={{
        sx: {
          borderRadius: "18px",
          overflow: "hidden",
          boxShadow: "0 24px 64px rgba(23,34,77,0.22)",
          maxHeight: { xs: "92vh", md: "86vh" },
        },
      }}
    >
      <Box
        sx={{
          position: "relative",
          px: { xs: 2.5, md: 4 },
          py: { xs: 2, md: 2.5 },
          background: "linear-gradient(135deg, #17224d 0%, #2f4d9a 55%, #759ae1 100%)",
          color: "#fff",
        }}
      >
        <Typography sx={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.14em", opacity: 0.8, mb: 0.5 }}>
          PLAN DETAILS
        </Typography>
        <Typography
          id="plan-learn-more-title"
          sx={{ fontWeight: 800, fontSize: { xs: 20, md: 26 }, lineHeight: 1.25, pr: 5 }}
        >
          {title}
        </Typography>
        <IconButton
          onClick={onClose}
          aria-label="Close"
          sx={{
            position: "absolute",
            right: 12,
            top: 12,
            color: "#fff",
            backgroundColor: "rgba(255,255,255,0.14)",
            "&:hover": { backgroundColor: "rgba(255,255,255,0.24)" },
          }}
        >
          <CloseIcon />
        </IconButton>
      </Box>
      <DialogContent
        sx={{
          p: 0,
          backgroundColor: "#f4f7fb",
        }}
      >
        <Box
          sx={{
            m: { xs: 2, md: 3 },
            p: { xs: 2, md: 3.5 },
            backgroundColor: "#fff",
            borderRadius: "14px",
            border: "1px solid #e4ebf6",
            boxShadow: "0 8px 24px rgba(23,34,77,0.06)",
          }}
        >
          <BlocksText
            content={content}
            sx={{
              color: "#2b3553",
              fontSize: 16,
              lineHeight: 1.75,
              "& h3": {
                color: "#17224d",
                fontSize: { xs: 22, md: 26 },
                fontWeight: 800,
                mt: 0,
                mb: 1.5,
              },
              "& h4, & h5": {
                color: "#2e74b5",
                fontSize: { xs: 17, md: 20 },
                fontWeight: 700,
                mt: 3,
                mb: 1.25,
                pl: 1.5,
                borderLeft: "4px solid #759ae1",
              },
              "& p": {
                fontSize: 16,
                lineHeight: 1.75,
                mb: 1.5,
              },
              "& strong": {
                fontWeight: 700,
                color: "#17224d",
              },
              "& ul, & ol": {
                pl: 0,
                mb: 2,
                listStyle: "none",
              },
              "& li": {
                position: "relative",
                fontSize: 15,
                lineHeight: 1.65,
                mb: 1,
                pl: 2.5,
                "&:before": {
                  content: '"•"',
                  position: "absolute",
                  left: 0,
                  color: "#759ae1",
                  fontWeight: 800,
                },
              },
              "& blockquote": {
                backgroundColor: "#eef3ff",
                borderLeft: "4px solid #759ae1",
                borderRadius: "0 10px 10px 0",
                px: 2,
                py: 1.5,
                color: "#17224d",
              },
            }}
          />
        </Box>
      </DialogContent>
    </Dialog>
  );
}
